const { withAppDelegate, withInfoPlist } = require("expo/config-plugins");

const SCENE_DELEGATE = `
// Cline scene lifecycle: generated by with-ios-scene-delegate.
class SceneDelegate: UIResponder, UIWindowSceneDelegate {
  var window: UIWindow?

  func scene(_ scene: UIScene, willConnectTo session: UISceneSession, options connectionOptions: UIScene.ConnectionOptions) {
    guard let windowScene = scene as? UIWindowScene,
          let appDelegate = UIApplication.shared.delegate as? AppDelegate,
          let factory = appDelegate.reactNativeFactory else { return }
    let window = UIWindow(windowScene: windowScene)
    self.window = window
    appDelegate.window = window
    var launchOptions: [UIApplication.LaunchOptionsKey: Any] = [:]
    if let context = connectionOptions.urlContexts.first {
      launchOptions[.url] = context.url
      if let source = context.options.sourceApplication {
        launchOptions[.sourceApplication] = source
      }
    }
    if let activity = connectionOptions.userActivities.first {
      launchOptions[.userActivityDictionary] = [
        "UIApplicationLaunchOptionsUserActivityTypeKey": activity.activityType,
        "UIApplicationLaunchOptionsUserActivityKey": activity
      ]
    }
    // Seed Expo Linking before JavaScript reads its initial URL.
    if let context = connectionOptions.urlContexts.first {
      _ = appDelegate.application(UIApplication.shared, open: context.url, options: [:])
    } else if let activity = connectionOptions.userActivities.first {
      _ = appDelegate.application(UIApplication.shared, continue: activity, restorationHandler: { _ in })
    }
    factory.startReactNative(withModuleName: "main", in: window, launchOptions: launchOptions)
  }

  func scene(_ scene: UIScene, openURLContexts URLContexts: Set<UIOpenURLContext>) {
    for context in URLContexts {
      _ = (UIApplication.shared.delegate as? AppDelegate)?.application(UIApplication.shared, open: context.url, options: [:])
    }
  }

  func scene(_ scene: UIScene, continue userActivity: NSUserActivity) {
    _ = (UIApplication.shared.delegate as? AppDelegate)?.application(UIApplication.shared, continue: userActivity, restorationHandler: { _ in })
  }
}
`;

function applySceneDelegate(source) {
	if (
		!source.includes("class AppDelegate: ExpoAppDelegate") ||
		!source.includes("var reactNativeFactory: RCTReactNativeFactory?")
	) {
		throw new Error(
			"Cline scene lifecycle requires the Expo Swift AppDelegate factory template. Review this plugin after upgrading Expo.",
		);
	}
	// Move React startup into the scene rather than creating a screen-based window
	// during didFinishLaunching. A scene manifest with the legacy launch path
	// causes an empty/crashing app on scene-required iOS runtimes.
	const legacyLaunch =
		/#if os\(iOS\) \|\| os\(tvOS\)\s+window = UIWindow\(frame: UIScreen\.main\.bounds\)\s+factory\.startReactNative\(\s*withModuleName: "main",\s*in: window,\s*launchOptions: launchOptions\)\s*#endif/;
	const migrated = source.replace(legacyLaunch, "");
	if (migrated.includes("window = UIWindow(frame: UIScreen.main.bounds)")) {
		throw new Error(
			"Cline could not migrate the AppDelegate window startup. Review the generated Swift before enabling scene lifecycle.",
		);
	}
	// Preserve the already-working local wrapper and repeated prebuilds.
	if (
		migrated.includes("class SceneDelegate: UIResponder, UIWindowSceneDelegate")
	)
		return migrated;
	if (migrated === source || migrated.includes("class SceneDelegate")) {
		throw new Error(
			"Cline scene lifecycle found an unexpected AppDelegate startup or existing SceneDelegate.",
		);
	}
	return `${migrated.trimEnd()}\n${SCENE_DELEGATE}`;
}

function applySceneManifest(infoPlist) {
	// This app uses a single React root; multiple UIKit scenes are not supported.
	const manifest = infoPlist.UIApplicationSceneManifest || {};
	const configurations = manifest.UISceneConfigurations || {};
	infoPlist.UIApplicationSceneManifest = {
		...manifest,
		UIApplicationSupportsMultipleScenes: false,
		UISceneConfigurations: {
			...configurations,
			UIWindowSceneSessionRoleApplication: [
				{
					UISceneConfigurationName: "Default Configuration",
					UISceneDelegateClassName: "$(PRODUCT_MODULE_NAME).SceneDelegate",
				},
			],
		},
	};
	return infoPlist;
}

function withIosSceneDelegate(config) {
	config = withAppDelegate(config, (mod) => {
		if (mod.modResults.language !== "swift") {
			throw new Error("Cline scene lifecycle requires a Swift AppDelegate.");
		}
		mod.modResults.contents = applySceneDelegate(mod.modResults.contents);
		return mod;
	});
	return withInfoPlist(config, (mod) => {
		mod.modResults = applySceneManifest(mod.modResults);
		return mod;
	});
}

module.exports = withIosSceneDelegate;
module.exports.applySceneDelegate = applySceneDelegate;
module.exports.applySceneManifest = applySceneManifest;
